CREATE UNIQUE INDEX "orderingrole_tenant_id_role_code" ON "ordering_roles" ("tenant_id", "role_code");
-- Modify "role_permissions" table
ALTER TABLE "role_permissions" DROP CONSTRAINT "role_permissions_pkey", DROP CONSTRAINT "role_permissions_permission_id", DROP CONSTRAINT "role_permissions_role_id", ALTER COLUMN "role_id" TYPE uuid, ADD COLUMN "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, ADD PRIMARY KEY ("id"), ADD CONSTRAINT "role_permissions_ordering_permissions_permission" FOREIGN KEY ("permission_id") REFERENCES "ordering_permissions" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, ADD CONSTRAINT "role_permissions_ordering_roles_role" FOREIGN KEY ("role_id") REFERENCES "ordering_roles" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
